script:
frappe.ui.form.on('Student', {
    refresh: function(frm) {
        if (!frm.doc.sales_invoice && frm.doc.course_enrolled && frm.doc.fee) {
            frm.add_custom_button('Generate Invoice', function() {
                frappe.call({
                    method: 'generate_student_invoice',
                    args: { student: frm.doc.name },
                    callback: function(r) {
                        if (r.message) {
                            frappe.msgprint('Invoice created: ' + r.message);
                            frm.reload_doc();
                        }
                    }
                });
            }).addClass('btn-primary');
        }
        if (frm.doc.sales_invoice) {
            frm.add_custom_button('View Invoice', function() {
                frappe.set_route('Form', 'Sales Invoice', frm.doc.sales_invoice);
            });
        }
    }
});

frappe.listview_settings['Item'] = frappe.listview_settings['Item'] || {};
frappe.listview_settings['Item'].onload = function(listview) {
    listview.page.add_action_item(__('Set Reorder Level'), function() {
        let selected = listview.get_checked_items();
        if (!selected.length) {
            frappe.msgprint('Please select at least one item first.');
            return;
        }
        let d = new frappe.ui.Dialog({
            title: 'Set Reorder Level for ' + selected.length + ' item(s)',
            fields: [
                {fieldname: 'warehouse', fieldtype: 'Link', options: 'Warehouse', label: 'Warehouse', reqd: 1},
                {fieldname: 'reorder_level', fieldtype: 'Float', label: 'Reorder Level', reqd: 1},
                {fieldname: 'reorder_qty', fieldtype: 'Float', label: 'Reorder Qty', reqd: 1},
            ],
            primary_action_label: 'Apply',
            primary_action(values) {
                d.hide();
                selected.forEach(function(item) {
                    frappe.call({
                        method: 'frappe.client.get',
                        args: { doctype: 'Item', name: item.name },
                        callback: function(r) {
                            let item_doc = r.message;
                            let existing = item_doc.reorder_levels.find(row => row.warehouse === values.warehouse);
                            if (existing) {
                                existing.warehouse_reorder_level = values.reorder_level;
                                existing.warehouse_reorder_qty = values.reorder_qty;
                            } else {
                                item_doc.reorder_levels.push({
                                    warehouse: values.warehouse,
                                    warehouse_reorder_level: values.reorder_level,
                                    warehouse_reorder_qty: values.reorder_qty,
                                    material_request_type: 'Purchase'
                                });
                            }
                            frappe.call({
                                method: 'frappe.client.save',
                                args: { doc: item_doc },
                                callback: function() {
                                    frappe.show_alert({message: item.name + ' updated', indicator: 'green'});
                                }
                            });
                        }
                    });
                });
            }
        });
        d.show();
    });
};
